mapper.select:
SELECT count(*)
FROM public.attendance_record
WHERE attendance_day_id = #{attendanceDayId}

mapper.update:
UPDATE public.attendance_day
SET status = 'CANCELED',
	canceled_by_account_id = #{actorAccountId},
	canceled_at = #{canceledAt},
	cancel_reason = #{reason}
WHERE id = #{attendanceDayId}
  AND department_id = #{departmentId}
  AND status = 'SCHEDULED'
  AND NOT EXISTS (
	SELECT 1
	FROM public.attendance_record
	WHERE attendance_day_id = #{attendanceDayId}
  )

UPDATE public.attendance_day
SET policy_version_id = #{policyVersionId}
	, finalization_due_at = #{finalizationDueAt}
WHERE id = #{attendanceDayId}
  AND department_id = #{departmentId}
  AND status = 'SCHEDULED'
  AND NOT EXISTS (
	SELECT 1
	FROM public.attendance_record
	WHERE attendance_day_id = #{attendanceDayId}
  )

UPDATE public.attendance_target
SET is_target = FALSE,
	changed_by_account_id = #{actorAccountId},
	changed_at = #{changedAt},
	change_reason = #{reason}
WHERE attendance_day_id = #{attendanceDayId}
  AND department_id = #{departmentId}
  AND member_id = #{memberId}
  AND is_target

mapper.select:
SELECT count(*)
FROM public.attendance_record
WHERE attendance_day_id = #{attendanceDayId}
  AND member_id = #{memberId}

SELECT department_id
FROM public.attendance_day
WHERE id = #{attendanceDayId}
